import{_ as s,l as o,o as e,c as d,v as t,p as i,x as n,d as l,i as A,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"磁盘几何与寻道","description":"","frontmatter":{"title":"磁盘几何与寻道","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hdd-geometry.md","filePath":"cs/hdd-geometry.md","lastUpdated":1789023840000}'),p={name:"cs/hdd-geometry.md"};function h(c,a,B,m,D,_){const r=o("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="磁盘几何与寻道" tabindex="-1">磁盘几何与寻道 <a class="header-anchor" href="#磁盘几何与寻道" aria-label="Permalink to &quot;磁盘几何与寻道&quot;">​</a></h1><div class="epigraph"><p>磁头要移动到目标磁道再等扇区转过来：机械延迟按毫秒计，地址在固件里从 CHS 改写成 LBA，操作系统看见的仍是块。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA；Tanenbaum and Bos, Modern Operating Systems 整理</footer></div><p><a href="/cs/ssd-gc-wear">上一课</a>的 SSD 没有寻道。<a href="/cs/disk-sched">磁盘调度</a>在 OS 课可能已谈电梯算法。缺口是硬件几何：<strong>柱面/磁头/扇区</strong>、寻道与旋转，以及为何今天仍要懂它——因为 HDD 还在冷数据层，且对照让 SSD 的并行更清楚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>盘片旋转，磁头臂径向移动。访问时间 ≈ 寻道 + 旋转等待 + 传输。外圈比特密度更高（ZBR），同角度扇区更多。缺口不是 FTL，而是：控制器把 LBA 映到物理扇区，坏扇区重映射（比 NAND 简单的替代区）。顺序大块传输摊薄寻道；随机 4K 被机械支配。</p><p>缓存：盘内 DRAM 缓冲写，掉电风险类似未持久的写回。</p><h3 id="lba-不是「没有几何了」" tabindex="-1">LBA 不是「没有几何了」 <a class="header-anchor" href="#lba-不是「没有几何了」" aria-label="Permalink to &quot;LBA 不是「没有几何了」&quot;">​</a></h3><p>主机接口放弃 CHS 编程，几何仍在盘内决定延迟。把 HDD 当均匀延迟块设备，调度器无法解释为何顺序快两个数量级。也不要把寻道当 PCIe 的 lane 训练。</p><p><span class="marginnote">Patterson/Hennessy 与 CA:AQA 用磁盘讲存储层次底部。Tanenbaum 有 CHS 与调度。本课不背某 RPM 型号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固件：逻辑地址 → 物理磁道/头/扇区，避开缺陷表。命令队列（NCQ）让盘内选最近扇区，类似 FR-FCFS 但对旋转位置。与 SSD：无擦除、可覆盖，无磨损均衡，有机械磨损（另一统计）。</p>',11)),(e(),i(E,null,{default:n(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LBA%5B%22LBA%22%5D%20--%3E%20MAP%5B%22%E7%9B%98%E5%86%85%E5%87%A0%E4%BD%95%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAP%20--%3E%20SEEK%5B%22%E5%AF%BB%E9%81%93%22%5D%0A%20%20SEEK%20--%3E%20ROT%5B%22%E6%97%8B%E8%BD%AC%E7%AD%89%E5%BE%85%22%5D%0A%20%20ROT%20--%3E%20XFER%5B%22%E6%89%87%E5%8C%BA%E4%BC%A0%E8%BE%93%22%5D%0A%20%20XFER%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%9D%97%E8%AE%BE%E5%A4%87%E5%A6%82%E4%BD%95%E6%8C%82%E4%B8%8A%20PCIe%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>RAID 与文件系统布局（柱面对齐）是上层；本课只交延迟来源。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课 PCIe 是互连，NVMe SSD 与部分 HDD 桥都坐在它上面。本课把「块设备内部」从闪存与磁盘两边讲完，接口层开始。DMA 稍后把块搬进内存，不经过 CPU 逐字拷。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲磁记录物理（垂直记录、HAMR）的材料细节，不进入光刻。不把磁带库几何写进主干。不讨论交易所托管机房的磁盘——本栏禁限价簿。</p><p>后课默认：HDD 延迟由寻道与旋转主导；对外仍是 LBA 块。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>寻道+旋转是毫秒级；ZBR 让外圈更快。</li><li>主机用 LBA；几何在固件。</li><li>对照 SSD：可覆盖、无 GC，但有机械。</li><li>出处：Patterson and Hennessy, COD；Hennessy and Patterson, CA:AQA；Tanenbaum and Bos。</li></ul>',8))])}const C=s(p,[["render",h]]);export{u as __pageData,C as default};
